pub struct Point {
    pub x: i64,
    pub y: i64,
}

pub fn manhattan(a: &Point, b: &Point) -> i64 {
    (a.x - b.x).abs() + (a.y - b.x).abs()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_records() {
        assert_eq!(manhattan(&Point { x: 1, y: 2 }, &Point { x: 4, y: -2 }), 7);
        assert_eq!(manhattan(&Point { x: 0, y: 0 }, &Point { x: 0, y: 0 }), 0);
    }
}
